   417	/*
   418	static uint32_t *
   419	_u32_memmem(uint32_t *haystack, size_t hlen, uint32_t *needle, size_t nlen)
   420	{
   421	  uint32_t *p;
   422	
   423	  if (nlen == 0)
   424	    return haystack;
   425	
   426	  for (p = haystack; hlen >= nlen; p++, hlen--)
   427	    {
   428	      if (*p == *needle && (nlen == 1 || u32_cmp(p, needle, nlen) == 0))
   429	        return p;
   430	    }
   431	
   432	  return NULL;
   433	}
   434	*/
   435	
   436	static uint8_t *
   437	_u8_memmem (uint8_t * haystack, size_t hlen, uint8_t * needle, size_t nlen)
   438	{
   439	  uint8_t *p;
   440	
   441	  if (nlen == 0)
   442	    return haystack;
   443	
   444	  for (p = haystack; hlen >= nlen; p++, hlen--)
   445	    {
   446	      if (*p == *needle && (nlen == 1 || memcmp (p, needle, nlen) == 0))
   447	        return p;
   448	    }
   449	
   450	  return NULL;
   451	}
   452	
   453	static size_t
   454	_u32_cp_stream_len (const uint8_t * stream, size_t ncp)
   455	{
   456	  const uint8_t *end;
   457	
   458	  for (end = stream; ncp; end++)
   459	    {
   460	      if ((*end & 0x80) == 0)
   461	        ncp--;
   462	    }
   463	
   464	  return end - stream;
   465	}
