   467	/* Remove doubled mappings. With Unicode 6.3.0 the mapping data shrinks
   468	 *  from 7272 to 4322 entries of uint32_t (29088 to 17288 bytes).
   469	 * Converting those 4322 uin32_t values to a uint8_t stream, we decrease mapping
   470	 *  table size from 17288 to 9153 bytes.
   471	 */
   472	static void
   473	_compact_idna_map (void)
   474	{
   475	  unsigned it;
   476	
   477	  /* sort into 'longest mappings first' */
   478	  qsort (idna_map, map_pos, sizeof (IDNAMap_gen),
   479	         (int (*)(const void *, const void *)) _compare_map_by_maplen);
   480	
   481	  uint8_t *data = calloc (sizeof (uint8_t), mapdata_pos), *p;
   482	  size_t ndata = 0, slen;
   483	
   484	  if (data == NULL)
   485	    abort();
   486	
   487	  for (it = 0; it < map_pos; it++)
   488	    {
   489	      IDNAMap_gen *map = idna_map + it;
   490	
   491	      if (!map->nmappings)
   492	        continue;
   493	
   494	      slen = _u32_cp_stream_len (genmapdata + map->offset, map->nmappings);
   495	
   496	      if ((p = _u8_memmem (data, ndata, genmapdata + map->offset, slen)))
   497	        {
   498	          map->offset = p - data;
   499	          continue;
   500	        }
   501	
   502	      memcpy (data + ndata, genmapdata + map->offset, slen);
   503	      map->offset = ndata;
   504	      ndata += slen;
   505	    }
   506	
   507	  memcpy (genmapdata, data, ndata);
   508	  mapdata_pos = ndata;
   509	  free (data);
   510	
   511	  /* sort into 'lowest codepoint first' */
   512	  qsort (idna_map, map_pos, sizeof (IDNAMap_gen),
   513	         (int (*)(const void *, const void *)) _compare_map);
   514	}
   515	
   516	static void
   517	_combine_idna_flags (void)
   518	{
   519	  unsigned it, it2;
   520	
   521	  /* There are not many different combinations of flags */
   522	  for (it = 0; it < map_pos; it++)
   523	    {
   524	      IDNAMap_gen *map = idna_map + it;
   525	      int found = 0;
   526	
   527	      for (it2 = 0; it2 < flag_combinations && !found; it2++)
   528	        {
   529	          if (flag_combination[it2] == map->flags)
   530	            {
   531	              map->flag_index = it2;
   532	              found = 1;
   533	            }
   534	        }
   535	
   536	      if (!found)
   537	        {
   538	          if (flag_combinations >= countof (flag_combination))
   539	            {
   540	              fprintf (stderr,
   541	                       "flag_combination[] too small - increase and retry\n");
   542	              exit (EXIT_FAILURE);
   543	            }
   544	          map->flag_index = flag_combinations++;
   545	          flag_combination[map->flag_index] = map->flags;
   546	        }
   547	    }
   548	  for (it = 0; it < map_pos; it++)
   549	    {
   550	      IDNAMap_gen *map = idna_map + it;
   551	
   552	      if (map->flags != flag_combination[map->flag_index])
   553	        {
   554	          fprintf (stderr, "Flags do not for 0x%X-0x%X)\n", map->cp1,
   555	                   map->cp2);
   556	          exit (EXIT_FAILURE);
   557	        }
   558	    }
   559	}
   560	
   561	static int
   562	_print_tr46_map (uint32_t min, uint32_t max, int do_print)
   563	{
   564	  unsigned it;
   565	  int it2, entries = 0;
   566	
   567	  for (it = 0; it < map_pos; it++)
   568	    {
   569	      const IDNAMap_gen *map = idna_map + it;
   570	      uint32_t cp2, cp1 = map->cp1, value, range;
   571	      int n;
   572	
   573	      if (cp1 < min)
   574	        continue;
   575	
   576	      if (cp1 > max)
   577	        break;
   578	
   579	      n = (map->cp2 - cp1) / 0x10000;
   580	
   581	      for (it2 = 0; it2 <= n; it2++, cp1 = cp2 + 1)
   582	        {
   583	          entries++;
   584	
   585	          if (it2 == n)
   586	            cp2 = map->cp2;
   587	          else
   588	            cp2 = cp1 + 0xFFFF;
   589	
   590	          if (!do_print)
   591	            continue;
   592	
   593	          range = cp2 - cp1;
   594	          value =
   595	            (((map->nmappings << 14) | map->offset) << 3) | map->flag_index;
   596	
   597	          if (max == 0xFF)
   598	            printf ("0x%X,0x%X,", cp1 & 0xFF, range & 0xFF);
   599	          else if (max == 0xFFFF)
   600	            printf ("0x%X,0x%X,0x%X,0x%X,",
   601	                    (cp1 >> 8) & 0xFF, cp1 & 0xFF,
   602	                    (range >> 8) & 0xFF, range & 0xFF);
   603	          else if (max == 0xFFFFFF)
   604	            printf ("0x%X,0x%X,0x%X,0x%X,0x%X,",
   605	                    (cp1 >> 16) & 0xFF, (cp1 >> 8) & 0xFF, cp1 & 0xFF,
   606	                    (range >> 8) & 0xFF, range & 0xFF);
   607	
   608	          printf ("0x%X,0x%X,0x%X,\n",
   609	                  (value >> 16) & 0xFF, (value >> 8) & 0xFF, value & 0xFF);
   610	        }
   611	    }
   612	
   613	  if (max == 0xFF)
   614	    return entries * 5;
   615	  if (max == 0xFFFF)
   616	    return entries * 7;
   617	  if (max == 0xFFFFFF)
   618	    return entries * 8;
   619	
   620	  return 0;
   621	}
