   623	int
   624	main (void)
   625	{
   626	  unsigned it;
   627	
   628	  // read IDNA mappings
   629	  if (_scan_file (SRCDIR "/IdnaMappingTable.txt", read_IdnaMappings))
   630	    return 1;
   631	
   632	  _compact_idna_map ();
   633	  _combine_idna_flags ();
   634	
   635	  // read NFC QuickCheck table
   636	  if (_scan_file (SRCDIR "/DerivedNormalizationProps.txt", read_NFCQC))
   637	    return 1;
   638	
   639	  qsort (nfcqc_map, nfcqc_pos, sizeof (NFCQCMap),
   640	         (int (*)(const void *, const void *)) _compare_map);
   641	
   642	  printf ("/* This file is automatically generated.  DO NOT EDIT! */\n\n");
   643	  printf ("#include <stdint.h>\n");
   644	  printf ("#include \"tr46map.h\"\n\n");
   645	
   646	  printf ("static const uint8_t idna_flags[%u] =\n{", flag_combinations);
   647	  for (it = 0; it < flag_combinations; it++)
   648	    {
   649	      printf ("0x%X,", flag_combination[it]);
   650	    }
   651	  printf ("};\n\n");
   652	
   653	  printf ("static const uint8_t idna_map_8[%d] = {\n",
   654	          _print_tr46_map (0x0, 0xFF, 0));
   655	  _print_tr46_map (0x0, 0xFF, 1);
   656	  printf ("};\n\n");
   657	
   658	  printf ("static const uint8_t idna_map_16[%d] = {\n",
   659	          _print_tr46_map (0x100, 0xFFFF, 0));
   660	  _print_tr46_map (0x100, 0xFFFF, 1);
   661	  printf ("};\n\n");
   662	
   663	  printf ("static const uint8_t idna_map_24[%d] = {\n",
   664	          _print_tr46_map (0x10000, 0xFFFFFF, 0));
   665	  _print_tr46_map (0x10000, 0xFFFFFF, 1);
   666	  printf ("};\n\n");
   667	
   668	  printf ("static const uint8_t mapdata[%u] = {\n", (unsigned) mapdata_pos);
   669	  for (it = 0; it < mapdata_pos; it++)
   670	    {
   671	      printf ("0x%02X,%s", genmapdata[it], it % 16 == 15 ? "\n" : "");
   672	    }
   673	  printf ("};\n\n");
   674	
   675	  printf ("static const NFCQCMap nfcqc_map[%u] = {\n", (unsigned) nfcqc_pos);
   676	  for (it = 0; it < nfcqc_pos; it++)
   677	    {
   678	      NFCQCMap *map = nfcqc_map + it;
   679	      printf ("{0x%X,0x%X,%d},\n", map->cp1, map->cp2, map->check);
   680	    }
   681	  printf ("};\n");
   682	
   683	  return 0;
   684	}
